// collapsesfx.js — user-supplied skyscraper collapse rumble, appended to the
// SFX pack (like carsfx/gunsfx/alarmsfx). Loaded AFTER soundfx.js and BEFORE
// game.js. Data-URL WAV (16kHz mono, downsampled from the 48kHz source);
// file:// safe. game.js maps it via SFX_MAP.towercollapse and plays it in
// startTowerCollapse() when a struck tower begins to come down.
if (typeof SFX_PACK !== "undefined") {
  SFX_PACK.towercollapse = ["data:audio/wav;base64,"];
}
